It is well known \cite{karatzas1991brownian} that the iterates $\{\alpha_k\}$ generated by the SGLD algorithm \eqref{eq:gen_dtsgld} are asymptotically, \color{black}{ as $\epsilon \to 0, \, k \to \infty$}, distributed according to the Gibbs measure 
\begin{equation}
\label{eq:gibbsd}
    \pi_{\infty}(\alpha) \propto \exp(-\beta J(\alpha))
\end{equation}

Then the inverse learner can incorporate these noisy gradient evaluations through the following \textit{passive} stochastic gradient Langevin dynamics (PSGLD) algorithm:
\begin{align}
\begin{split}
\label{eq:dt_psgld}
    \alpha_{k+1} =\ &\alpha_k - \epsilon\biggl[K(\theta_k,\alpha_k) \frac{\beta}{2}\hat{\nabla} J (\theta_k) \color{black}{-} \nabla \pi_0(\alpha_k)\biggr]\pi_0(\alpha_k) + \sqrt{\epsilon}\pi_0(\alpha_k) w_k
\end{split}
\end{align}
where  $K(\cdot,\cdot)$ is a kernel function, $\epsilon$ is the step size and $w_k$ is purposefully injected Gaussian noise.

Denote 
 \begin{equation}
 \label{eq:dtlaw_def}
     \pi_{k} := \textrm{Law}(\alpha_k)
 \end{equation}
 i.e., $\pi_{k}$ is the sampling measure of PSGLD algorithm at iterate $k\in\mathbb{N}$.

Specifically, the forward learner produces 
\begin{equation}
\label{eq:dgproc}
\{\hat{\nabla}J(\theta_k), \theta_k\in\mathbb{R}^{N}\},\,\, k\in [k^*] := 1,\dots,k^*
\end{equation}
where $\hat{\nabla}J(\theta_k)$ denotes a noisy gradient of cost function $J$ evaluated at iterate $\theta_k$.

\caption{Forward Learner. Re-Initializing SGD Process}\label{alg:sgd}
\begin{algorithmic}[1]
\State initialize $k=0$ 
\State \textcolor{black}{determine terminating condition $\mathcal{T}_k: \{\mathcal{F}_i, i\leq k\} \to \{0,1\}$}
\While{$\mathcal{T}_k = 0$}
    \State $\theta_{k} \overset{iid}{\sim} \pi_{0,\gamma}$

    \While{$\|\hat{\nabla}J(\theta_k)\| \geq c_{opt}$}
        \State $\theta_{k+1} \gets \theta_k - \eta\hat{\nabla} J (\theta_k)$ 
        \State $k = k+1$
        \State \textcolor{black}{set $\mathcal{T}_k: \{\theta_0, \dots,\theta_k\} \to \{0,1\}$} \textcolor{black}{\algorithmiccomment{Set to 1 when terminating condition is satisfied}}
        \textcolor{black}{\If{$\mathcal{T}_k = 1$}
        \State $k^* = k$, \text{break}
        \EndIf}
    \EndWhile
\EndWhile
\end{algorithmic}

In \cite{stramer1999langevin} more general reversible diffusions of the form, with $\sigma: \mathbb{R}^{N} \to \mathbb{R}$ differentiable,  
\begin{equation}
\label{eq:stram_diff}
    d\theta(t) = \left[-\frac{\beta}{2}\hat{\nabla}J(\theta)dt \,\color{black}{+}\, \nabla\sigma(\theta)dt + dW(t) \right]\sigma(\theta)
\end{equation}
are studied, and it is shown \color{black}{in \cite{krishnamurthy2021langevin}} that \eqref{eq:stram_diff} has the same stationary measure \eqref{eq:gibbsd} as the classical Langevin diffusion \eqref{eq:langdiff}. {\color{black} We list this as a technical result, given by Lemma~\ref{lem:gendiffstat} in Appendix~\ref{ap:techres}.}

The corresponding Euler-Maruyama time discretization of \eqref{eq:stram_diff} results in the following discrete-time Markov process 
\begin{align}
\label{eq:stram_disc}
    &\theta_{k+1} = \theta_k - \epsilon\left[\frac{\beta}{2}\nabla J(\theta_k) \,\color{black}{-}\, \nabla\sigma(\theta_k) \right]\sigma(\theta_k) + \sqrt{\epsilon}\sigma(\theta_k)w_k
\end{align}
which can thus equivalently be used as a MCMC sampler, \color{black}{in the sense described for the simpler SGLD \eqref{eq:LD}}, from \eqref{eq:gibbsd}. We will  utilize the generalized process \eqref{eq:stram_disc}, as opposed to the classical SGLD \eqref{eq:LD}, for our PSGLD algorithm\footnote{See \cite{krishnamurthy2021langevin} for motivation}. 

\textit{Active vs. Passive Gradient Evaluation}: Notice that the above SGLD algorithms utilize, at each time step, the unbiased gradient $\hat{\nabla}J(\theta_k)$ evaluated at the current iterate $\theta_k$. We term this \textit{active} gradient evaluation, and distinguish this from \textit{passive} gradient evaluation, where the gradient is evaluated at a different (uncontrolled) point. The following section introduces the adaptive IRL setting and motivates the need for passive gradient evaluation in our PSGLD algorithm.

\caption{PSGLD for IRL}\label{alg:psgld}
\begin{algorithmic}[1]
\State parameters: step size $\epsilon$, inverse temperature $\beta$, kernel scale $\Delta$, re-sampling distribution scale $\gamma$
\State initialize $\alpha_0 \sim \pi_{0,\gamma}$
\While{$k \geq 0$}
        \State obtain $\theta_k$ from Algorithm~\ref{alg:sgd}
        \If{$k\geq 1$}
        \State $\hat{\nabla}J(\theta_k) = \frac{1}{\eta}(\theta_k-\theta_{k-1}),\quad K_{k-1} = \frac{1}{\Delta^N} K(\frac{\theta_{k-1} - \alpha_{k-1}}{\Delta})$
        \State sample $w_k \sim \mathcal{N}(0,I_{N})$
        \State  $\alpha_k \gets \alpha_{k-1} - \epsilon\biggl[K_{k-1} \frac{\beta}{2} \hat{\nabla} J (\theta_k) \,\color{black}{-}\, \nabla \pi_{0,\gamma}(\alpha_{k-1})\biggr]\pi_{0,\gamma}(\alpha_{k-1})+ \sqrt{\epsilon}\pi_{0,\gamma}(\alpha_{k-1}) w_k$
        \EndIf
\EndWhile


\end{algorithmic}

\label{prop:wca}
    Let $\alpha^{\epsilon}(t) = \alpha_k$ for $t \in [\epsilon k, \epsilon (k+1)]$ be the continuous-time interpolation of PSGLD \eqref{eq:dt_sgld}. Under assumptions (A1)-(A4) of \cite{krishnamurthy2021langevin}, the process $\alpha^{\epsilon}(t)$ converges weakly to the solution of the stochastic differential equation
    \begin{gather}
    \begin{aligned}
    \begin{split}
    \label{eq:ct_diff}
    &d\alpha(t) = -\left[\frac{\beta}{2}\pi_{0,\gamma}^2(\alpha(t))\nabla J(\alpha(t)) \,\color{black}{-}\, \nabla\pi_{0,\gamma}(\alpha(t))\pi_{0,\gamma}(\alpha(t))\right]dt + \pi_{0,\gamma}(\alpha(t))dW(t) \\
    &\alpha(0) = \alpha_0 \sim \pi_{0,\gamma}
    \end{split}
    \end{aligned}\raisetag{0\baselineskip}
    \end{gather}
where $W(t)$ is standard $N$-dimensional Brownian motion. Furthermore, the stochastic differential equation \eqref{eq:ct_diff} has $\pi_{\infty}$ \eqref{eq:gibbsd} as its stationary distribution.

