\label{thm:main1}
     Consider the PSGLD Algorithm~\ref{alg:psgld} with iterates $\alpha_k \in \mathbb{R}^{N}$. Recall $c_{LS}$ is the logarithmic-Sobolev constant for diffusion process~\eqref{eq:ct_diff} ($c_{LS}$ will be bounded in \eqref{eq:lsconst}). For any 
     \begin{equation}
    \label{eq:delmax}
     \delta \in \left[0,\exp\left(-\frac{1}{\beta c_{LS}}\right)\right]
    \end{equation}
    choose step size $\epsilon$ according to \eqref{eq:stepspec}, number of iterations $k$ according to \eqref{eq:itspec}, kernel scale $\Delta$ according to \eqref{eq:delspec}, and sampling distribution $\pi_{0,\gamma}$ with $\gamma$ satisfying \eqref{eq:omegaspec}. Then, under assumptions (\ref{ass:Msmooth})-(\ref{ass:beta}), the 2-Wasserstein distance between the distribution $\pi_{k}$, generated by the PSGLD algorithm, and the Gibbs measure $\pi_{\infty}$ \eqref{eq:gibbsd}, satisfies: 
    \begin{align}
    \begin{split}
    \label{eq:wassbound}
       &\mathcal{W}_2(\pi_{k},\pi_{\infty}) \leq \delta\left[C_4 + \sqrt{2c_{LS} C_3} \right] + \delta\sqrt{10c_{LS}N\log\left(1/\delta\right)}
    \end{split}
    \end{align}
    $C_3, C_4$ are constants dependent on structural specifications of $J$ and the process \eqref{eq:dt_sgld}, provided explicitly in Appendix~\ref{ap:bd_consts}. $c_{LS}$ is the logarithmic-Sobolev constant bounded explicitly in Proposition~\ref{prop:logsob}.

{\color{black}
\caption{\color{black}{Cost Reconstruction by Sequential-Sampling Kernel Density Estimation}}\label{alg:costrec}
\begin{algorithmic}[1]
\State Initialize 2-Wasserstein proximity $\rho > 0$, number of sampling streams $T$, sampling region $\Theta \subset \mathbb{R}^{N}$
\State \textcolor{black}{Set kernel function $\mathcal{K}$ and $T$-dependent bandwidth $b_T$.}
\State Take $\delta \in \textcolor{black}{\left[0, \exp\left(-\frac{1}{\beta c_{LS}}\right) \right]}$ s.t. $\delta\left[C_4 + \sqrt{2c_{LS} C_3} \right] + \delta\sqrt{10c_{LS}N\log\left(1/\delta\right)} \leq \rho$, \,\,$\epsilon \leq \left(\frac{\delta}{\log(1/\delta)} \right)^2$, $\hat{k}$ as \eqref{eq:itspec} 
\State Initialize parameters $\Delta, \gamma$ as \eqref{eq:delspec}, \eqref{eq:omegaspec}, respectively.



\State Set $k=0, \,S=\emptyset, \,q=0$.
\For{$i=1: \textcolor{black}{T}$}
\State \textcolor{black}{Initialize $i$'th PSGLD (Algorithm~\ref{alg:psgld}) stream by $\alpha_0^i \overset{\textcolor{black}{i.i.d.}}{\sim} \pi_{0,\gamma}$}.



\While{$k \leq \textcolor{black}{q +} \hat{k}$}   
    \State $k = k+1$ \textcolor{black}{\algorithmiccomment{Iterate $i$'th Algorithm 2 stream, taking $\hat{\nabla}J(\theta_k)$ from Algorithm~\ref{alg:sgd} as input.}}
    \If{$k = \textcolor{black}{q +} \hat{k}$}
        \State \textcolor{black}{Take sample $\alpha_k^i$} \textcolor{black}{\algorithmiccomment{Sample from $\pi_{\hat{k}}$. By initializations (Lines 1-3) we have $\mathcal{W}_2(\pi_{\hat{k}},\pi_{\infty}) \leq \rho$.}}
        \If{$\alpha_k^i \in \Theta$}

            \State \textcolor{black}{$S \leftarrow S \cup \alpha_k^i$}
        \EndIf
    \EndIf
\EndWhile
\textcolor{black}{\While{$\|\hat{\nabla}J(\theta_k)\| > c_{opt}$} \algorithmiccomment{Wait until SGD (Algorithm~\ref{alg:sgd}) re-initializes.}
\EndWhile}
\State \textcolor{black}{$q = k$} \textcolor{black}{\algorithmiccomment{$q$ is a dummy variable holding the re-initialization iterate value}}
\EndFor

\textcolor{black}{\If{$|S| \geq 1$}
    \State \textcolor{black}{Set $b_S = b_T\sqrt{\frac{T}{|S|}}$, and construct density estimate $\hat{\pi}(\cdot) = \frac{1}{b_S |S|}\sum_{\alpha_k^i \in S}\mathcal{K}\left(\frac{\cdot - \alpha_k^i}{b_S^{1/N}} \right)$.}


\State \textcolor{black}{Construct cost function $\hat{J}(\cdot) = -\frac{1}{\beta}\log(\hat{\pi}(\cdot))$, for $\beta$ in Algorithm~\ref{alg:psgld}.}
\EndIf}
\end{algorithmic}
}

\label{thm:kernest}
    Consider the reconstructed cost function $\hat{J}(\cdot)$ from Algorithm~\ref{alg:costrec}. Then, given Assumptions \ref{ass:Msmooth} to \ref{as:kernspec}, the following $L^1$ reconstruction error concentration inequality holds, valid for $x > \rho\sqrt{ 2C_6}(\sqrt{\xi}|\Theta|)^{-1}$:

    \begin{align}
     \begin{split}
     \label{eq:phidef}
        &\mathbb{P}\left(\int_{\Theta}|\hat{J}(\theta) - J(\theta)|d\theta \geq  \phi_{x,{\color{black}T }}\right) \leq 1 - (1 - 2\exp(-\psi_{x,{\color{black}{\color{black}T }}}^2))(1-2\exp(-2y^2/T^3))\\
        &\text{ where} \;\;\phi_{x,{\color{black}T }} = 2 L|\Theta|\left(\frac{x}{\sqrt{{\color{black}T }}b_T} + \frac{\mathcal{K}_2}{(2\pi)^{N}\sqrt{{\color{black}T }}b_T} + \frac{1}{2}\mathcal{K}_3\mathcal{K}_4 \left(b_T\textcolor{black}{\sqrt{\frac{1}{P_{\Theta}}+y}}\right)^{2/N} \right), \\
       & \quad \quad \psi_{x,{\color{black}T }} = \frac{x|\Theta|\sqrt{\xi} - \sqrt{2C_6}\rho}{\sqrt{\xi}|\Theta|\sqrt{b_T}}.
    \end{split}
\end{align}
    Here $\Theta$ is the compact set over which the parameters are restricted, \textcolor{black}{with size $|\Theta| := \int_{\Theta}du$},  $L=
\exp(\beta T_1)$ where $T_1$ is an upper bound on $J$ in $\Theta$ \textcolor{black}{(existing by \ref{ass:Msmooth})}, $N$ is the dimension, constants $\mathcal{K}_1, \mathcal{K}_2,\mathcal{K}_3,\mathcal{K}_4$ are defined in \ref{as:kernspec}, $b_T$ is the kernel bandwidth, $\xi$ is defined in \eqref{eq:Zint},  $C_6$ is defined in A\ref{ap:bd_consts}, and $x$ and $y$ are a free variable over which the concentration inequality may range.

Let $X_t$ be an $\mathbb{R}^{N}$-valued diffusion defined by the stochastic differential equation
\begin{equation}
\label{eq:itodiff}
    dX_t = b(X_t)\, dt + \sigma(X_t)\, dW(t), \quad X_0 = x \in \mathbb{R}^{N}
\end{equation}
where $b: \mathbb{R}^{N} \to \mathbb{R}^{N}$ is the drift function, $\sigma: \mathbb{R}^{N} \to \mathbb{R}$ is the volatility function, and $W(t)$ is standard $N$-dimensional Brownian motion.

\begin{equation}
\label{eq:itodiff}
    dX_t = b(X_t)\, dt + \sigma(X_t)\, dW(t), \quad X_0 = x \in \mathbb{R}^{N}
\end{equation}

Let $\mathcal{L}$ be the \textit{infinitesimal generator} of $X_t$, defined by its action on compactly-supported $C^2$ functions $f:\mathbb{R}^{N}\to\mathbb{R}$ in domain $\mathcal{D}(\mathcal{L}) \subseteq C^2(\mathbb{R}^{N})$, as
\begin{align}
    \begin{split}
        \mathcal{L} f(x) &= \lim_{t \downarrow 0}\frac{\mathbb{E}^x[f(X_t) - f(x)]}{t} = \sum_{i=1}^n b_i(x) \frac{\partial f}{\partial x_i}(x) + \frac{1}{2}\sum_{i,j} \sigma^2(x) \frac{\partial^2 f}{\partial x_i \partial x_j}(x)
    \end{split}
\end{align}
where $b_i(x)$ is the $i$'th element of $b(x) \in \mathbb{R}^{N}$.

\begin{align}
    \begin{split}
        \mathcal{L} f(x) &= \lim_{t \downarrow 0}\frac{\mathbb{E}^x[f(X_t) - f(x)]}{t} = \sum_{i=1}^n b_i(x) \frac{\partial f}{\partial x_i}(x) + \frac{1}{2}\sum_{i,j} \sigma^2(x) \frac{\partial^2 f}{\partial x_i \partial x_j}(x)
    \end{split}
\end{align}

define the \textit{Dirichlet form}
\[ \mathcal{E}(g) := -\int_{\mathbb{R}^{N}}g\mathcal{L} g d\pi\]
and the \textit{spectral gap} $\lambda$ as 
\begin{align}
\begin{split}
\label{eq:sgap}
\lambda &:= \inf\bigl\{\frac{\int_{\mathbb{R}^{N}}\mathcal{E}(g) d\pi}{\int_{\mathbb{R}^{N}}g^2 d\pi} \ : \ g \in C^1(\mathbb{R}^{N})\cap L^2(\pi),\,g \neq 0,\, \int_{\mathbb{R}^{N}}gd\pi_{\infty} = 0 \bigr\} \\

\end{split}
\end{align}

Let us consider a Markov process $X_t$ with unique invariant distribution $\pi$ and infinitesimal generator $\mathcal{L}$.

We say that $\pi$ satisfies a \textit{Poincar\'e (spectral gap) inequality} with constant $c$ if 
\begin{equation}
\label{eq:poinc_ineq}
    \chi^2(\mu || \pi) \leq c\, \mathcal{E}\left(\sqrt{\frac{d\mu}{d\pi}}\right)
\end{equation} for all probability measures $\mu \ll \pi$ ($\mu$ absolutely continuous w.r.t $\pi$),
where \\ $\chi^2(\mu || \pi) := ||\frac{d\mu}{d\pi} - 1||^2_{L^2(\pi)}$ is the $\chi^2$ divergence between $\mu$ and $\pi$.

