where $\textrm{Var}(\cdot)$ denotes variance w.r.t. the probability measure inducing the expectation, $\theta_{\bar{s}_{-1}} := \theta_{\lfloor (s-\epsilon) / \epsilon\rfloor }$ and we use the relation $ \textrm{Var}\left(\frac{1}{\|\nabla J(\theta_{\bar{s}})\|}\right) \leq \frac{1/c_{opt}}{\textrm{Var}(\|\nabla J(\theta_{\bar{s}})\|)} \leq \frac{1/c_{opt}}{\textrm{Var}(\|\nabla J(\theta_{\bar{s}})\| | \theta_{\bar{s}_{-1}})}$. Now we bound each constituent summation term. 


\textbf{First Term:}
By $L_{\nabla J}$-smoothness (Assumption~\ref{ass:Msmooth}), we begin to control the first term as:
\begin{align*}
&\mathbb{E}\|\nabla J(\bar{\alpha}(s)) - \nabla J(\bar{\alpha}(\lfloor s / \epsilon \rfloor \epsilon))\|^2
\leq L_{\nabla J}^2 \mathbb{E}\| (\bar{\alpha}(s) - \bar{\alpha}(\lfloor s / \epsilon \rfloor \epsilon)) \|^2 
\end{align*}
Then for $s \in [j\epsilon, (j+1)\epsilon]$:\\
\begin{flalign*}
&(\bar{\alpha}(s) - \bar{\alpha}(\lfloor s / \epsilon \rfloor \epsilon))\\
& = (s-j\epsilon)\frac{\beta}{2}K_{\Delta}(\theta_j,\bar{\alpha}(j\epsilon))\hat{\nabla}J(\theta_j)\pi_{0,\gamma}(\bar{\alpha}(j\epsilon)) \\
&\quad  + (s-j\epsilon)\pi_{0,\gamma}(\bar{\alpha}(j\epsilon))\nabla\pi_{0,\gamma}(\bar{\alpha}(j\epsilon))- \pi_{0,\gamma}(\bar{\alpha}(j\epsilon))(W(s) - W(j\epsilon))
\end{flalign*}
Then bound $\mathbb{E}\|(\bar{\alpha}(s) - \bar{\alpha}(\lfloor s / \epsilon \rfloor \epsilon)) \|^2$ as:
\begin{align}
\begin{split}
\label{eq:MSEexp}
&\mathbb{E}\|(\bar{\alpha}(s) - \bar{\alpha}(\lfloor s / \epsilon \rfloor \epsilon)) \|^2 \\
&\leq 6\epsilon^2\mathbb{E}\|K_{\Delta}(\theta_j,\bar{\alpha}(j\epsilon))\frac{\beta}{2}\hat{\nabla}J(\theta_j)\|^2\mathbb{E}\|\pi_{0,\gamma}(\bar{\alpha}(j\epsilon))\|^2 \\
&\quad + 3\epsilon^2\mathbb{E}\|\pi_{0,\gamma}(\bar{\alpha}(j\epsilon))\nabla\pi_{0,\gamma}(\bar{\alpha}(j\epsilon)) \|^2  + 3\epsilon\mathbb{E}\|\pi_{0,\gamma}(\bar{\alpha}(j\epsilon))(W(s)-W(j\epsilon)\|^2\\


\end{split}
\end{align}

But observe that
\begin{align}
\begin{split}
\label{eq:MSEexpp}
    \mathbb{E}\|(\bar{\alpha}(s) -& \bar{\alpha}(\lfloor s / \epsilon \rfloor \epsilon))\|^2 \\&= \mathbb{E}\left[(s-j\epsilon)^2\|K_{\Delta}(\theta_j,\bar{\alpha}(j\epsilon))\hat{\nabla}J(\theta_j)\pi_{0,\gamma}(\bar{\alpha}(j\epsilon))\|^2\right]\\
    &\quad + \mathbb{E}\left[ (s-j\epsilon)^2\|\pi_{0,\gamma}(\bar{\alpha}(j\epsilon))\nabla\pi_{0,\gamma}(\bar{\alpha}(j\epsilon))\|^2\right] \\
    &\quad + 2\mathbb{E}\left[(s-j\epsilon)^2\langle K_{\Delta}(\theta_j,\bar{\alpha}(j\epsilon))\hat{\nabla}J(\theta_j),\,\pi_{0,\gamma}^2(\bar{\alpha}(j\epsilon))\nabla\pi_{0,\gamma}(\bar{\alpha}(j\epsilon))\rangle\right] \\
    &\quad - \mathbb{E}\left[ (s-j\epsilon)\langle K_{\Delta}(\theta_j),\bar{\alpha}(j\epsilon))\hat{\nabla}J(\theta_j),\,\pi_{0,\gamma}^2(W(s)-W(j\epsilon))\rangle\right]\\
    &\quad - \mathbb{E}\left[(s-j\epsilon)\langle\nabla\pi_{0,\gamma}(\bar{\alpha}(j\epsilon)),\,\pi_{0,\gamma}^2(W(s)-W(j\epsilon)\rangle \right] \\
    &\quad + \mathbb{E}\left[\pi_{0,\gamma}^2\|\bar{\alpha}(j\epsilon))(W(s)-W(j\epsilon)\|^2\right]
\end{split}
\end{align}
then combining \eqref{eq:MSEexpp} with \eqref{eq:MSEexp}, and using the Martingale property of Brownian motion, Jensen's Inequality, and Cauchy-Schwarz, gives:
\begin{align*}
    &\mathbb{E}\left[\pi_{0,\gamma}^2(\bar{\alpha}(j\epsilon))\|W(s)-W(j\epsilon)\|^2\right] \\&\leq 2\epsilon^2\mathbb{E}\|K_{\Delta}(\theta_j,\bar{\alpha}(j\epsilon))\hat{\nabla}J(\theta_j)\pi_{0,\gamma}(\bar{\alpha}(j\epsilon))\|^2 \\
    &\quad + 2\epsilon^2\mathbb{E}\|\pi_{0,\gamma}(\bar{\alpha}(j\epsilon))\nabla\pi_{0,\gamma}(\bar{\alpha}(j\epsilon))\|^2 \\&\quad + \epsilon^2\sqrt{\mathbb{E}\left[\|\langle K_{\Delta}(\theta_j,\bar{\alpha}(j\epsilon))\hat{\nabla}J(\theta_j)\pi_{0,\gamma}^2(\bar{\alpha}(j\epsilon)),\, \pi_{0,\gamma}^2(\bar{\alpha}(j\epsilon))\nabla\pi_{0,\gamma}(\bar{\alpha}(j\epsilon)) \rangle\|^2\right]} \\
    &\leq 2\epsilon^2\mathbb{E}\|K_{\Delta}(\theta_j,\bar{\alpha}(j\epsilon))\hat{\nabla}J(\theta_j)\pi_{0,\gamma}(\bar{\alpha}(j\epsilon))\|^2 \\
    &\quad + 2\epsilon^2\mathbb{E}\|\pi_{0,\gamma}(\bar{\alpha}(j\epsilon))\nabla\pi_{0,\gamma}(\bar{\alpha}(j\epsilon))\|^2 \\&\quad +\epsilon^2\sqrt{\mathbb{E}\|K_{\Delta}(\theta_j,\bar{\alpha}(j\epsilon))\hat{\nabla}J(\theta_j)\pi_{0,\gamma}(\bar{\alpha}(j\epsilon))\|^2} \\&\quad + \epsilon^2\sqrt{\mathbb{E}\|\pi_{0,\gamma}(\bar{\alpha}(j\epsilon))\nabla\pi_{0,\gamma}(\bar{\alpha}(j\epsilon))\|^2} 
\end{align*}
Thus we have:
\begin{align*}
    &\mathbb{E}\|(\bar{\alpha}(s) - \bar{\alpha}(\lfloor s / \epsilon \rfloor \epsilon)) \|^2 \\
    &\leq 18\epsilon^2\mathbb{E}\|K_{\Delta}(\theta_j,\bar{\alpha}(j\epsilon))\frac{\beta}{2}\hat{\nabla}J(\theta_j)\|^2\mathbb{E}\|\pi_{0,\gamma}(\bar{\alpha}(j\epsilon))\|^2 \\
    &\quad + 9\epsilon^2\mathbb{E}\|\pi_{0,\gamma}(\bar{\alpha}(j\epsilon))\nabla\pi_{0,\gamma}(\bar{\alpha}(j\epsilon)) \|^2 \\
    &\quad + 3\epsilon^2\sqrt{\mathbb{E}\|K_{\Delta}(\theta_j,\bar{\alpha}(j\epsilon))\frac{\beta}{2}\hat{\nabla}J(\theta_j)\|^2\mathbb{E}\|\pi_{0,\gamma}(\bar{\alpha}(j\epsilon))\|^2} \\
    &\quad  + 3\epsilon^2\sqrt{\mathbb{E}\|\pi_{0,\gamma}(\bar{\alpha}(j\epsilon))\nabla\pi_{0,\gamma}(\bar{\alpha}(j\epsilon)) \|^2} \\
    &\leq \epsilon^4\left(72C_0+ 18\right) + \epsilon^3\left(6\sqrt{C_0} +\sqrt{2}\right)
\end{align*}

where recall $C_0 := 3L_{\nabla J}^2(M_{\theta} + 2B^2M_{\theta}) + B^2 + \zeta$.
